CREATE TABLE IF NOT EXISTS site_settings(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1),settings jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS site_pages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,title text NOT NULL DEFAULT '',seo_title text NOT NULL DEFAULT '',seo_description text NOT NULL DEFAULT '',published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS page_sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),page_id uuid NOT NULL REFERENCES site_pages(id) ON DELETE CASCADE,section_type text NOT NULL CHECK(section_type IN ('hero','story','benefits','products','testimonials','faq','newsletter','imageText')),content jsonb NOT NULL DEFAULT '{}'::jsonb,styles jsonb NOT NULL DEFAULT '{}'::jsonb,visible boolean NOT NULL DEFAULT true,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS page_sections_page_order_idx ON page_sections(page_id,sort_order);
CREATE TABLE IF NOT EXISTS newsletter_subscribers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
